    void denyHealthPermissions(){org.robolectric.Shadows.shadowOf(RuntimeEnvironment.getApplication()).denyPermissions(HealthReader.PERMISSIONS);org.robolectric.Shadows.shadowOf(RuntimeEnvironment.getApplication()).denyPermissions(HealthCatalog.permissions());org.robolectric.Shadows.shadowOf(RuntimeEnvironment.getApplication()).denyPermissions(MedicalReader.permissions());}
    @Test @Config(sdk=36) public void preservesNativeSdkValuesAndMedicalDocument()throws Exception {HealthCatalogChecks.run();}
    @Test @Config(sdk=34) public void oldDeviceShowsUnavailableTypesWithoutReadingMedicalApi()throws Exception {denyHealthPermissions();assertFalse(MedicalReader.supported());org.json.JSONObject data=new HealthReader(RuntimeEnvironment.getApplication()).browse();assertEquals(54,data.getJSONArray("availability").length());assertEquals(0,data.getJSONArray("healthRecords").length());}
    @Test @Config(sdk=36) public void currentDeviceListsEveryTypeWithoutPermission()throws Exception {denyHealthPermissions();org.json.JSONObject data=new HealthReader(RuntimeEnvironment.getApplication()).browse();assertEquals(54,data.getJSONArray("availability").length());assertEquals(0,data.getJSONArray("healthRecords").length());for(int i=0;i<54;i++){String state=data.getJSONArray("availability").getJSONObject(i).getString("status");assertTrue(state.equals("permission")||state.equals("unsupported"));}}
    @Test @Config(sdk=34) public void articleSearchAndBookmarksUseOfflineCatalog()throws Exception {org.robolectric.android.controller.ActivityController<ArticleActivity> controller=org.robolectric.Robolectric.buildActivity(ArticleActivity.class).setup();ArticleActivity app=controller.get();assertEquals(10,app.articles.length());app.query="호흡";app.renderList();assertEquals(1,app.list.getChildCount());assertTrue(app.list.getChildAt(0).hasOnClickListeners());app.savedOnly=true;app.renderList();assertFalse(app.list.getChildAt(0).hasOnClickListeners());app.prefs.edit().putBoolean("mind-breathe",true).commit();app.renderList();assertTrue(app.list.getChildAt(0).hasOnClickListeners());controller.pause().stop().destroy();}
    @Test @Config(sdk=34,qualifiers="night") public void galaxyArticleScreenKeepsSearchAndReadableNightSurfaces(){org.robolectric.android.controller.ActivityController<ArticleActivity> c=org.robolectric.Robolectric.buildActivity(ArticleActivity.class).setup();ArticleActivity a=c.get();assertTrue(a.night());android.view.ViewGroup content=a.findViewById(android.R.id.content);android.widget.EditText search=findSearch(content);assertNotNull(search);search.setText("호흡");org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(200));assertEquals(1,a.list.getChildCount());assertEquals(a.foreground(),search.getCurrentTextColor());assertEquals(a.surface(),((android.graphics.drawable.GradientDrawable)a.list.getChildAt(0).getBackground()).getColor().getDefaultColor());c.pause().stop().destroy();}
    @Test @Config(sdk=34,qualifiers="night") public void galaxyMainScreenStartsAndNavigatesInNightMode(){org.robolectric.android.controller.ActivityController<EnhancedActivity> c=org.robolectric.Robolectric.buildActivity(EnhancedActivity.class).setup();EnhancedActivity a=c.get();assertEquals(a.foreground(),a.INK);a.tab=2;a.render();assertTrue(a.page.getChildCount()>0);assertEquals(a.background(),a.BACK);c.pause().stop().destroy();}
    @Test @Config(sdk=34) public void journalRedesignKeepsSearchFiltersAndPeriodSelection()throws Exception{org.robolectric.android.controller.ActivityController<EnhancedActivity> c=org.robolectric.Robolectric.buildActivity(EnhancedActivity.class).setup();EnhancedActivity a=c.get();a.entries.clear();a.entries.add(new org.json.JSONObject().put("kind","마음").put("value",3).put("date",System.currentTimeMillis()).put("note","테스트"));a.tab=3;a.render();android.widget.EditText search=findSearch(a.page);assertNotNull(search);search.setText("테스트");assertTrue(a.results.getChildCount()>1);findDescription(a.page,"filter-2").performClick();assertEquals(2,a.selectedFilter);findDescription(a.page,"journal-days-7").performClick();assertEquals(7,a.journalDays);assertEquals("기록",((android.widget.TextView)findDescription(a.page,"galaxy-page-title")).getText().toString());c.pause().stop().destroy();}
    @Test @Config(sdk=34) public void oneUiTitleCollapsesAndMenuShowsInstalledVersion(){org.robolectric.android.controller.ActivityController<EnhancedActivity> c=org.robolectric.Robolectric.buildActivity(EnhancedActivity.class).setup();EnhancedActivity a=c.get();android.view.ViewGroup content=a.findViewById(android.R.id.content);android.widget.TextView title=(android.widget.TextView)findDescription(content,"galaxy-compact-title");assertEquals(0f,title.getAlpha(),0f);android.widget.ScrollView scroll=(android.widget.ScrollView)findDescription(content,"galaxy-page-scroll");content.measure(android.view.View.MeasureSpec.makeMeasureSpec(a.dp(360),android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(a.dp(640),android.view.View.MeasureSpec.EXACTLY));content.layout(0,0,a.dp(360),a.dp(640));scroll.scrollTo(0,a.dp(220));assertEquals(1f,title.getAlpha(),0f);assertNotNull(findDescription(content,"open-goals"));findDescription(content,"galaxy-page-menu").performClick();assertNotNull(org.robolectric.shadows.ShadowPopupMenu.getLatestPopupMenu());c.pause().stop().destroy();}
    @Test @Config(sdk=34) public void floatingBottomMenuSwitchesAllTabsAndExposesSelection(){org.robolectric.android.controller.ActivityController<EnhancedActivity> c=org.robolectric.Robolectric.buildActivity(EnhancedActivity.class).setup();EnhancedActivity a=c.get();String[] ids={"home","mood","health","history"};for(int index=0;index<4;index++){android.view.ViewGroup content=a.findViewById(android.R.id.content);findDescription(content,"nav-"+ids[index]).performClick();content=a.findViewById(android.R.id.content);for(int n=0;n<4;n++){android.view.View item=findDescription(content,"nav-"+ids[n]);assertEquals(index==n,item.isSelected());assertTrue(item.isFocusable());}assertEquals(index,a.tab);assertNotNull(findDescription(content,"galaxy-bottom-menu"));}c.pause().stop().destroy();}
    @Test @Config(sdk=26) public void sleepSessionRestoresFreezesFinishAndDoesNotDuplicate()throws Exception{android.content.Context context=RuntimeEnvironment.getApplication();SleepTools.Store first=new SleepTools.Store(context,1000000);first.start(1000000);first.checkpoint(2000000);SleepTools.Store restored=new SleepTools.Store(context,2000000);assertEquals(first.session.getString("id"),restored.session.getString("id"));org.json.JSONObject record=restored.finish(1000000+8*3600000,15,20);SleepTools.validate(record);assertEquals((480-15-20)/60.0,record.getDouble("value"),0.0001);org.json.JSONObject retry=restored.finish(1000000+9*3600000,0,0);assertEquals(record.toString(),retry.toString());restored.reset();assertNull(new SleepTools.Store(context,1000000+9*3600000).session);}
    @Test @Config(sdk=34) public void sleepRejectsClockRollbackTooShortAndOverlappingStages()throws Exception{SleepTools.Store store=new SleepTools.Store(RuntimeEnvironment.getApplication(),1000000);store.start(1000000);store.checkpoint(2000000);store.observe(3000000);try{store.finish(2500000,0,0);fail();}catch(IllegalArgumentException expected){}try{SleepTools.hours(1000000,1030000,0,0);fail();}catch(IllegalArgumentException expected){}assertEquals(30,SleepTools.span(java.util.Arrays.asList(1430.0,20.0)),0.001);assertTrue(Double.isNaN(SleepTools.span(java.util.List.of(100.0))));store.reset();}
    @Test @Config(sdk=26) public void sleepToolsLaunchOnOldAndroidWithoutHealthApis(){org.robolectric.android.controller.ActivityController<SleepActivity> c=org.robolectric.Robolectric.buildActivity(SleepActivity.class).setup();SleepActivity a=c.get();a.mode=1;a.render();assertNotNull(findDescription(a.page,"sleep-tracking-start"));a.mode=2;a.render();assertNotNull(findDescription(a.page,"sleep-health-import"));c.pause().stop().destroy();}
    @Test @Config(sdk=26) public void extendedBackupPreservesUnitsAndRejectsMalformedFields()throws Exception{org.json.JSONObject record=new org.json.JSONObject().put("id","hc:test-pressure").put("recordType","BloodPressureRecord").put("date",System.currentTimeMillis()-1000).put("title","혈압").put("category","생체").put("fields",new org.json.JSONObject().put("systolic",new org.json.JSONObject().put("inMillimetersOfMercury",120.25)));org.json.JSONObject data=new org.json.JSONObject().put("healthRecords",new org.json.JSONArray().put(record));HealthArchive.save(RuntimeEnvironment.getApplication(),data);assertEquals(record.toString(),HealthArchive.load(RuntimeEnvironment.getApplication()).getJSONArray("healthRecords").getJSONObject(0).toString());assertEquals(1,HealthArchive.merge(data,data).getJSONArray("healthRecords").length());record.put("recordType","unknown");try{HealthArchive.validate(data);fail();}catch(org.json.JSONException expected){}}
    @Test @Config(sdk=34) public void articleRankingUsesOnlyConsentedKindsAndInterest()throws Exception{android.content.SharedPreferences p=RuntimeEnvironment.getApplication().getSharedPreferences("rank-test",0);org.json.JSONObject sleep=new org.json.JSONObject().put("id","sleep").put("topic","수면"),mind=new org.json.JSONObject().put("id","mind").put("topic","마음");org.json.JSONArray catalog=new org.json.JSONArray().put(sleep).put(mind);assertEquals("sleep",ArticleRank.sorted(catalog,p,java.util.Collections.emptySet()).get(0).getString("id"));p.edit().putBoolean("interest:마음",true).commit();assertEquals("mind",ArticleRank.sorted(catalog,p,java.util.Collections.emptySet()).get(0).getString("id"));assertFalse(p.getBoolean("use-records",false));assertEquals(2,ArticleRank.score(sleep,p,java.util.Set.of("수면"))-ArticleRank.score(sleep,p,java.util.Collections.emptySet()));}
    @Test @Config(sdk=34) public void practiceCanSelectThirtyCompletedDaysAndShowDetails(){org.robolectric.android.controller.ActivityController<PracticeActivity> c=org.robolectric.Robolectric.buildActivity(PracticeActivity.class).setup();PracticeActivity a=c.get();findDescription(a.page,"insights-window-30").performClick();assertEquals(30,a.analysisDays);findDescription(a.page,"insights-details").performClick();assertNotNull(org.robolectric.shadows.ShadowDialog.getLatestDialog());c.pause().stop().destroy();}
    @Test @Config(sdk=26) public void iosExtendedBackupCanRestoreExportAndBrowseWithoutHealthConnect()throws Exception{org.robolectric.android.controller.ActivityController<EnhancedActivity> c=org.robolectric.Robolectric.buildActivity(EnhancedActivity.class).setup();EnhancedActivity a=c.get();org.json.JSONObject nativeRecord=new org.json.JSONObject().put("id","hc:ios-pressure").put("recordType","BloodPressureRecord").put("date",System.currentTimeMillis()-1000).put("title","혈압").put("category","생체").put("fields",new org.json.JSONObject().put("systolic",new org.json.JSONObject().put("inMillimetersOfMercury",120.5)));org.json.JSONObject backup=new org.json.JSONObject().put("version",4).put("entries",new org.json.JSONArray()).put("healthRecords",new org.json.JSONArray().put(nativeRecord));a.validateBackup(backup);a.restore(backup);assertEquals(4,a.backup().getInt("version"));assertEquals(120.5,a.backup().getJSONArray("healthRecords").getJSONObject(0).getJSONObject("fields").getJSONObject("systolic").getDouble("inMillimetersOfMercury"),0.00001);a.restore(backup);assertEquals(1,a.backup().getJSONArray("healthRecords").length());org.robolectric.android.controller.ActivityController<HealthDataActivity> browser=org.robolectric.Robolectric.buildActivity(HealthDataActivity.class).setup();assertNotNull(findDescription(browser.get().findViewById(android.R.id.content),"health-record-search"));browser.get().showRecordDetails(nativeRecord);assertNotNull(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog());browser.pause().stop().destroy();c.pause().stop().destroy();}
    @Test @Config(sdk=26) public void browserFiltersDeviceAndDateWithoutInventingRecords()throws Exception{long now=System.currentTimeMillis();org.json.JSONObject first=new org.json.JSONObject().put("id","hc:b").put("recordType","HeartRateRecord").put("title","심박").put("category","생체").put("date",now-1000).put("fields",new org.json.JSONObject().put("metadata",new org.json.JSONObject().put("device",new org.json.JSONObject().put("model","Galaxy Watch"))));org.json.JSONObject old=new org.json.JSONObject(first.toString()).put("id","hc:old").put("date",now-40L*86400000);org.json.JSONObject future=new org.json.JSONObject(first.toString()).put("id","hc:future").put("date",now+10000);org.json.JSONArray data=new org.json.JSONArray().put(old).put(first).put(future);assertEquals(1,HealthBrowser.filter(data,7,"watch",now).length());assertEquals(2,HealthBrowser.filter(data,0,"심박",now).length());assertEquals(0,HealthBrowser.filter(data,7,"없는 기기",now).length());}
    @Test @Config(sdk=26) public void browserFavoritesPersistAndFilterRetainsSourceRecord()throws Exception{android.content.Context ctx=RuntimeEnvironment.getApplication();org.json.JSONObject r=new org.json.JSONObject().put("id","hc:heart").put("recordType","HeartRateRecord").put("title","심박").put("category","생체").put("date",System.currentTimeMillis()-1000).put("fields",new org.json.JSONObject());HealthArchive.save(ctx,new org.json.JSONObject().put("healthRecords",new org.json.JSONArray().put(r)));org.robolectric.android.controller.ActivityController<HealthDataActivity> c=org.robolectric.Robolectric.buildActivity(HealthDataActivity.class).setup();HealthDataActivity a=c.get();android.widget.CheckBox favorite=(android.widget.CheckBox)findDescription(a.body,"health-favorite-HeartRateRecord");assertNotNull(favorite);favorite.setChecked(true);a.favoritesOnly=true;a.searchQuery="심박";a.periodDays=7;a.renderRecords();assertNotNull(findDescription(a.recordList,"health-type-HeartRateRecord"));a.searchQuery="없는 기록";a.renderRecords();assertNull(findDescription(a.recordList,"health-type-HeartRateRecord"));c.pause().stop().destroy();org.robolectric.android.controller.ActivityController<HealthDataActivity> second=org.robolectric.Robolectric.buildActivity(HealthDataActivity.class).setup();assertTrue(second.get().favorites.getBoolean("HeartRateRecord",false));assertEquals(1,HealthArchive.load(ctx).getJSONArray("healthRecords").length());second.pause().stop().destroy();}
    @Test @Config(sdk=26) public void journalRecreationRestoresTabSearchAndDateFilter(){org.robolectric.android.controller.ActivityController<EnhancedActivity> c=org.robolectric.Robolectric.buildActivity(EnhancedActivity.class).setup();EnhancedActivity a=c.get();a.tab=3;a.query="산책";a.journalDays=7;a.selectedFilter=3;a.range=90;a.render();c.recreate();a=c.get();assertEquals(3,a.tab);assertEquals("산책",a.query);assertEquals(7,a.journalDays);assertEquals(3,a.selectedFilter);assertEquals(90,a.range);c.pause().stop().destroy();}
